<h2>Build a campaign tracking URL</h2><p class="lead">Create consistent UTM parameters and see the final URL immediately.</p><div class="form-grid"><div class="field full"><label for="base">Destination URL</label><input id="base" type="url" value="https://example.com/landing-page"></div><div class="field"><label for="source">utm_source</label><input id="source" value="linkedin" placeholder="google, newsletter, linkedin"><small>Traffic source or platform.</small></div><div class="field"><label for="medium">utm_medium</label><input id="medium" value="paid-social" placeholder="cpc, email, paid-social"><small>Marketing channel.</small></div><div class="field"><label for="campaign">utm_campaign</label><input id="campaign" value="fall-launch" placeholder="fall-launch"></div><div class="field"><label for="term">utm_term (optional)</label><input id="term" placeholder="keyword-or-audience"></div><div class="field full"><label for="content">utm_content (optional)</label><input id="content" placeholder="blue-button, video-a"></div></div><div class="tool-actions"><label class="helper"><input type="checkbox" id="normalize" checked> Normalize UTM values to lowercase hyphenated text</label><button class="btn btn-primary" id="build">Build URL</button><button class="btn btn-secondary" id="copy">Copy URL</button></div><div class="result-box"><pre class="code-output" id="out"></pre></div>
<script>(()=>{const $=i=>document.getElementById(i),keys=['source','medium','campaign','term','content'];const norm=v=>v.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');function go(){try{const u=new URL($('base').value);keys.forEach(k=>{let v=$(k).value.trim();if($('normalize').checked)v=norm(v);const p='utm_'+k;if(v)u.searchParams.set(p,v);else u.searchParams.delete(p)});$('out').textContent=u.toString()}catch(e){$('out').textContent='Enter a valid absolute destination URL, including https://.'}}document.querySelectorAll('input').forEach(x=>x.addEventListener('input',go));$('build').onclick=go;$('copy').onclick=()=>tkCopy($('out').textContent);go()})();</script>
